"""Addresses take their region from the Kemendagri list (regions.Village). The old free-text
city is kept by appending it to the street line, so nothing is lost before the region is chosen."""

import django.db.models.deletion
from django.db import migrations, models


def keep_city(apps, schema_editor):
    for model_name in ('businessplace', 'organization'):
        model = apps.get_model("tenants", model_name)
        for row in model.objects.exclude(city=""):
            row.address = ", ".join(part for part in (row.address.strip(), row.city.strip()) if part)[:500]
            row.save(update_fields=["address"])


